import numpy as np
import time
from scipy.signal import fftconvolve


def _R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    L = np.concatenate(([0.0], L, [0.0]))
    l2 = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    l1 = s * s
    linf = L.max()
    if linf <= 0:
        return -1.0
    return l2 / (l1 * linf)


def _trapezoid(N, a, b):
    h = np.zeros(N)
    c = (N - 1) / 2.0
    for i in range(N):
        d = abs(i - c)
        if d <= a:
            h[i] = 1.0
        elif d <= a + b:
            h[i] = (a + b - d) / b
        else:
            h[i] = 0.0
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    N = 50000
    best = None
    best_score = -1.0
    a_vals = [0, 500, 1000, 2000, 4000, 8000]
    b_vals = [500, 1000, 2000, 4000, 8000, 16000]
    for a in a_vals:
        for b in b_vals:
            if time.process_time() - t0 > budget_seconds * 0.8:
                break
            h = _trapezoid(N, a, b)
            sc = _R(h)
            if sc > best_score:
                best_score = sc
                best = h
        if time.process_time() - t0 > budget_seconds * 0.8:
            break

    # compare with start
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.any(s > 0):
            sc_s = _R(s)
            if sc_s > best_score:
                return s

    if best is None:
        return np.ones(50)
    return best

import numpy as np
import time
from scipy.optimize import minimize


def _R_of(h):
    h = np.maximum(np.asarray(h, dtype=float).ravel(), 0.0)
    s = h.sum()
    if s <= 0:
        return -1.0
    c = np.convolve(h, h)
    L = np.concatenate(([0.0], c, [0.0]))
    seg = L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]
    l2 = seg.sum() / 3.0
    mx = L.max()
    if mx <= 0:
        return -1.0
    return l2 / (s * s * mx)


def _resample(h, M):
    h = np.asarray(h, dtype=float).ravel()
    N = h.size
    if N == M:
        return h.copy()
    xp = np.linspace(0.0, 1.0, N)
    x = np.linspace(0.0, 1.0, M)
    return np.interp(x, xp, h)


def _profile(a, p, q, N):
    x = np.linspace(-1.0, 1.0, N)
    ax = np.abs(x)
    h = np.zeros(N)
    inner = ax <= a
    h[inner] = 1.0
    outer = (~inner) & (ax <= 1.0)
    if np.any(outer):
        t = (ax[outer] - a) / max(1e-9, (1.0 - a))
        t = np.clip(t, 0.0, 1.0)
        h[outer] = np.maximum(0.0, 1.0 - t ** q) ** p
    return h


def _coord_polish(h, best_R, deadline, N, passes=3):
    h = np.maximum(h.astype(float), 0.0)
    if h.max() > 0:
        h = h / h.max()
    factors = [1.02, 1.005, 0.995, 0.98]
    for _ in range(passes):
        improved = False
        for i in range(N):
            if time.process_time() >= deadline:
                return h, best_R
            base = h[i]
            for f in factors:
                h[i] = base * f
                r = _R_of(h)
                if r > best_R:
                    best_R = r
                    base = h[i]
                    improved = True
                else:
                    h[i] = base
        if not improved:
            break
    return h, best_R


def _refine(h, best_R, deadline, N):
    """Coordinate polish with a finer ladder of multiplicative factors,
    plus a second pass with additive bumps. Keeps the best observed."""
    h = np.maximum(h.astype(float), 0.0)
    if h.max() > 0:
        h = h / h.max()
    # multiplicative polish, finer factors
    factors = [1.01, 1.004, 1.0015, 0.9985, 0.996, 0.99]
    for _ in range(2):
        improved = False
        for i in range(N):
            if time.process_time() >= deadline:
                return h, best_R
            base = h[i]
            best_local = base
            for f in factors:
                h[i] = base * f
                r = _R_of(h)
                if r > best_R:
                    best_R = r
                    best_local = h[i]
                    improved = True
                else:
                    h[i] = best_local
            h[i] = best_local
        if not improved:
            break
    # additive polish near the top region
    if time.process_time() < deadline:
        s = h.sum()
        mean = s / N if N else 0.0
        for i in range(N):
            if time.process_time() >= deadline:
                return h, best_R
            base = h[i]
            for d in (0.01 * mean, 0.003 * mean, -0.003 * mean, -0.01 * mean):
                h[i] = max(0.0, base + d)
                r = _R_of(h)
                if r > best_R:
                    best_R = r
                    base = h[i]
                else:
                    h[i] = base
    return h, best_R


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + max(0.0, budget_seconds - 2.0)

    best_h = None
    best_R = -1.0

    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size and s.size <= 50000 and np.isfinite(s).all() and s.sum() > 0:
            s = np.maximum(s, 0.0)
            r = _R_of(s)
            if r > best_R:
                best_R = r
                best_h = s.copy()

    if best_h is None:
        x = np.linspace(-1.0, 1.0, 400)
        best_h = np.exp(-4.0 * np.abs(x) ** 2)
        best_R = _R_of(best_h)

    # --- Parametric family optimization at N=1000 ---
    N_opt = 1000
    fam_deadline = min(deadline, time.process_time() + 16.0)

    def negR(p):
        a = float(np.clip(p[0], 0.0, 0.95))
        pp = float(np.clip(p[1], 0.1, 8.0))
        q = float(np.clip(p[2], 0.1, 8.0))
        return -_R_of(_profile(a, pp, q, N_opt))

    starts = [(0.5, 2.0, 2.0), (0.3, 2.0, 2.0), (0.6, 1.5, 3.0),
              (0.4, 3.0, 1.5), (0.2, 2.0, 4.0), (0.7, 2.0, 2.0)]
    fam_best = None
    fam_best_R = -1.0
    for a0, p0, q0 in starts:
        if time.process_time() >= fam_deadline:
            break
        try:
            res = minimize(negR, x0=np.array([a0, p0, q0]), method='Nelder-Mead',
                           options={'xatol': 1e-4, 'fatol': 1e-8, 'maxiter': 600})
            a = float(np.clip(res.x[0], 0.0, 0.95))
            pp = float(np.clip(res.x[1], 0.1, 8.0))
            q = float(np.clip(res.x[2], 0.1, 8.0))
            r = _R_of(_profile(a, pp, q, N_opt))
            if r > fam_best_R:
                fam_best_R = r
                fam_best = (a, pp, q)
        except Exception:
            continue

    if fam_best is not None:
        a, pp, q = fam_best
        h4 = _profile(a, pp, q, 4000)
        r4 = _R_of(h4)
        print("family params a=%.4f p=%.4f q=%.4f R(N=1000)=%.6f R(N=4000)=%.6f"
              % (a, pp, q, fam_best_R, r4))
        if r4 > best_R:
            best_R = r4
            best_h = h4.copy()

    # --- Resample the incumbent to N=2000 and polish it first ---
    N_pol = 2000
    hp = _resample(best_h, N_pol)
    rp = _R_of(hp)
    if rp > best_R:
        best_R = rp
        best_h = hp.copy()

    # Quick coarse polish to get a good starting point
    if time.process_time() < deadline:
        hp, rp = _coord_polish(hp, rp, deadline, N_pol, passes=2)
        if rp > best_R:
            best_R = rp
            best_h = hp

    # --- Fine refinement with the improved ladder ---
    if time.process_time() < deadline:
        hf, rf = _refine(np.asarray(best_h, float), best_R, deadline, best_h.size)
        if rf > best_R:
            best_R = rf
            best_h = hf

    print("final R=%.6f N=%d" % (best_R, best_h.size))

    h = np.maximum(best_h, 0.0)
    if h.sum() <= 0:
        h = np.ones(50)
    return h
